def can_reach_edge_5_path(grid, start_comp, target_directions):
    """For a component, can a 5-path from its boundary reach some edge in target_directions."""
    h, w = len(grid), len(grid[0])

    # Get all boundary cells (cells of component touching 5s)
    boundary_sides = set()
    for r, c in start_comp:
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 5:
                boundary_sides.add(((nr, nc), dr, dc))

    # BFS from boundary 5s to see what edges they can reach
    visited_5 = set()
    for (bor, dr, dc), side in boundary_sides:
        queue = [(bor, dr, dc)]
        visited_5.add((bor, dr, dc))

        while queue:
            curr, dpr, dpc = queue.pop(0)
            r, c = curr
            side_direction = (dpr, dpc)  # the direction we came from

            # Follow 5s and check for edge
            for nr, nc in [(r + dpr, c), (r, c + dpc)]:
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 5:
                    neighbor = (nr, nc)
                    if (neighbor, dpr, dpc) not in visited_5:
                        visited_5.add((neighbor, dpr, dpc))

                        # Check if this path reaches a system edge
                        if r == 0 or r == h - 1 or c == 0 or c == w - 1:
                            return True

            # Also check alternative directions from this 5
            for nr, nc in [(r + dpr, c), (r, c + dpc)]:
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 5:
                    if (neighbor := (nr, nc)) not in [bor for (bor, _ , _) in visited_5]:
                        pass  # Already visited
            # Continue BFS in original direction
            for far_r, far_c in [(r + 2 * dpr, c), (r, c + 2 * dpc)]:
                if 0 <= far_r < h and 0 <= far_c < w and grid[far_r][far_c] == 5:
                    if (far_r, far_c, dpr, dpc) not in visited_5:
                        visited_5.add((far_r, far_c, dpr, dpc))
                        queue.append((far_r, far_c, dpr, dpc))

    return False

